// ① PLAN DEL DÍA · CEREBRO · PONERSE AL DÍA (diario) · CC#2 · relevo 18 (2026-10-08) · firmado por Emilio: sitio + sedes + Instagram propio. Competidores y anuncios: NO.
// Este nodo SOLO LEE y decide qué se hace, con los TOPES ESCRITOS AQUÍ. El nodo ② ejecuta lo que este nodo deja en `acciones` (y vuelve a comprobar el tope antes de cada llamada).
// «Cliente activo» = ALTA REALIZADA (Emilio 08-oct): no archivado ni dado de baja, con manual de marca y plan de 90 días. El alta no se toca.
const SB = 'https://ordaeyxvvvdqsznsecjx.supabase.co'
const API = 'https://zero-risk-platform.vercel.app'
const auth = { apikey: $env.SUPABASE_SERVICE_ROLE_KEY, Authorization: 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY }
const UUID = /^[0-9a-fA-F-]{36}$/
let viaWebhook = false
let entrada = {}
try { const w = $('Webhook · a mano (con llave)').first(); viaWebhook = true; entrada = (w.json && w.json.body) || {} } catch (e) { viaWebhook = false }
const SOLO = typeof entrada.cliente === 'string' && UUID.test(entrada.cliente) ? entrada.cliente : null
// por horario SIEMPRE se ejecuta; a mano solo si se pide `ejecutar: true` Y se nombra UN cliente (limita el alcance de una prueba)
const EJECUTAR = viaWebhook ? (entrada.ejecutar === true && SOLO !== null) : true
const DIAS = 1

// ── lo medido (243 corridas reales de Apify) · US$ por corrida
const COSTO = {
  website_content_scraper: { prom: 0.0228, max: 0.0536 },
  instagram_scraper: { prom: 0.0023, max: 0.0023 },
  recolectar_sedes: { prom: 0, max: 0 },
}
// ── TOPES ESCRITOS EN EL FLUJO (firmados): nada que vigilar
const TOPE_CORRIDAS_POR_CLIENTE_DIA = 6
const TOPE_USD_POR_CLIENTE_DIA = 0.3
const TOPE_USD_TOTAL_DIA = 3.0
// ── ETIQUETADO DIARIO (relevo 21 · firmado): fotos PROPIAS nuevas sin etiqueta, una llamada al modelo por foto (≈ US$ 0,009 medido en las 16 reales; peor caso 0,0286). Topes escritos aquí:
const TOPES_ETIQUETAR = { fotos_por_cliente_dia: 5, usd_dia: 0.1, intentos_por_foto: 2, peor_caso_usd: 0.0286 }
const POR_TABLA = { client_web_pages: 'pagina', client_social_images: 'instagram', client_sede_datos: 'sedes', client_sedes: 'sedes' }

const leer = async (url, headers) => this.helpers.httpRequest({ url, method: 'GET', json: true, headers, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 25000 })
const rest = async (ruta) => {
  const r = await leer(SB + '/rest/v1/' + ruta, auth)
  if (r.statusCode !== 200) throw new Error('LECTURA_FALLIDA · ' + ruta.slice(0, 60) + ' · HTTP ' + r.statusCode)
  return r.body
}
// una corrida de Apify puede dejar VARIAS filas en `apify_raw` (el Servicio guarda una por página leída, con el mismo instante): una corrida = función + segundo de creación
const corridasDe = (filas) => { const vistas = {}; for (const r of filas) vistas[r.apify_function + '|' + String(r.created_at).slice(0, 19)] = r.apify_function; return Object.keys(vistas).map((k) => vistas[k]) }
const norm = (h) => String(h || '').trim().toLowerCase().replace(/^@/, '')

const hoy0 = new Date(); hoy0.setUTCHours(0, 0, 0, 0)
const clientes = await rest('clients?select=id,name,status,archived_at,config&order=created_at.asc&limit=500')
// gasto máximo calculado de HOY en todos los clientes (corridas reales ya hechas × su máximo medido) para el tope total
const hoyTodos = await rest('apify_raw?select=apify_function,created_at&ensayo=eq.false&created_at=gte.' + hoy0.toISOString() + '&limit=1000')
let usdTotalHoyMax = 0
for (const f of corridasDe(hoyTodos)) usdTotalHoyMax += (COSTO[f] ? COSTO[f].max : 0.0536)

const salida = { flujo: 'EZXAFQvKZsJlvGNO', via: viaWebhook ? 'webhook a mano' : 'horario', ejecutar: EJECUTAR, solo_cliente: SOLO, generado_en: new Date().toISOString(), topes: { corridas_por_cliente: TOPE_CORRIDAS_POR_CLIENTE_DIA, usd_por_cliente: TOPE_USD_POR_CLIENTE_DIA, usd_total: TOPE_USD_TOTAL_DIA, etiquetar: TOPES_ETIQUETAR }, clientes: [], excluidos: [] }

for (const c of clientes) {
  if (SOLO && c.id !== SOLO) continue
  const esPrueba = /^prueba/i.test(String(c.id)) || /^prueba/i.test(String(c.name))
  const baja = ['churned', 'archived', 'inactive', 'lost', 'cancelled'].includes(String(c.status))
  const [manual, plan] = await Promise.all([
    rest('client_brand_books?select=id&client_id=eq.' + c.id + '&limit=1'),
    rest('client_historical_outputs?select=id,provenance_tag&client_id=eq.' + c.id + '&output_type=eq.campaign_plan_90d&limit=5'),
  ])
  const planReal = (plan || []).filter((p) => !(p.provenance_tag && typeof p.provenance_tag === 'object' && Object.keys(p.provenance_tag).some((k) => k.indexOf('prueba') === 0)))
  const motivos = []
  if (esPrueba) motivos.push('cliente de prueba')
  if (c.archived_at) motivos.push('archivado')
  if (baja) motivos.push('dado de baja (' + c.status + ')')
  if (!manual.length) motivos.push('sin manual de marca')
  if (!planReal.length) motivos.push('sin plan de 90 días')
  if (motivos.length) { salida.excluidos.push({ cliente: c.id, nombre: c.name, motivos }); continue }

  const hoyC = await rest('apify_raw?select=apify_function,created_at&client_id=eq.' + c.id + '&ensayo=eq.false&created_at=gte.' + hoy0.toISOString() + '&limit=200')
  const hoyCorridas = corridasDe(hoyC)
  let corridas = hoyCorridas.length, usdMax = 0
  for (const f of hoyCorridas) usdMax += (COSTO[f] ? COSTO[f].max : 0.0536)
  const acciones = [], no_hace = []
  const pedir = (funcion, params, detalle) => {
    const k = COSTO[funcion]
    if (corridas >= TOPE_CORRIDAS_POR_CLIENTE_DIA || usdMax + k.max > TOPE_USD_POR_CLIENTE_DIA || usdTotalHoyMax + k.max > TOPE_USD_TOTAL_DIA) { no_hace.push({ funcion, detalle, por_que: 'no cabe en el tope del día' }); return }
    corridas += 1; usdMax += k.max; usdTotalHoyMax += k.max
    acciones.push({ tipo: 'apify', funcion, params, detalle, usd_prom: k.prom, usd_max: k.max })
  }

  // 1 · lo vencido, agrupado por su FILA de origen (tabla → raspador: correspondencia estructural)
  const v = await leer(API + '/api/brain/portero/vencidos?cliente=' + c.id + '&dias=' + DIAS, { 'x-api-key': $env.INTERNAL_API_KEY })
  let sedes = false
  const vencidasAntes = []
  if (v.statusCode !== 200 || !v.body || v.body.estado === 'error_de_lectura') {
    no_hace.push({ detalle: 'no se pudo leer `vencidos` (HTTP ' + v.statusCode + ')', por_que: 'un fallo de lectura NUNCA se lee como «no vence nada»' })
  } else {
    for (const f of (v.body.vencidas || [])) vencidasAntes.push(f.ref)
    const grupos = new Map()
    for (const f of (v.body.vencidas || []).concat(v.body.por_vencer || [])) {
      const origen = String(f.ref || '').split('#')[0]
      const g = grupos.get(origen) || { origen, tabla: origen.split(':')[0], fichas: 0 }
      g.fichas += 1; grupos.set(origen, g)
    }
    for (const g of grupos.values()) {
      const que = POR_TABLA[g.tabla]
      const det = g.fichas + ' ficha(s) de ' + g.origen.slice(0, 48)
      if (que === 'pagina') {
        const fila = await rest('client_web_pages?select=url,owner_role&id=eq.' + g.origen.split(':')[1] + '&limit=1')
        const propia = fila[0] && fila[0].owner_role === 'propio'
        if (!fila[0] || !fila[0].url) no_hace.push({ detalle: det, por_que: 'la página de origen no tiene dirección' })
        else if (!propia) no_hace.push({ detalle: det, por_que: 'página de un competidor: competidores NO están firmados en esta ronda' })
        else pedir('website_content_scraper', { url: fila[0].url }, det + ' · ' + fila[0].url)
      } else if (que === 'sedes') {
        sedes = true
      } else if (que === 'instagram') {
        // las fotos propias no vencen; si alguna lo hiciera, la corrida de Instagram de abajo ya las cubre
      } else {
        no_hace.push({ detalle: det, por_que: 'su tabla (' + g.tabla + ') no se renueva raspando en esta ronda' })
      }
    }
  }
  // 2 · novedades propias: Instagram propio (la cuenta sale de la ficha del cliente; si falta, de sus fotos propias)
  const cfgIg = norm(c.config && c.config.apify && c.config.apify.own_handles && c.config.apify.own_handles.instagram)
  let handle = cfgIg
  if (!handle) { const fp = await rest('client_social_images?select=handle&client_id=eq.' + c.id + '&owner_role=eq.propio&limit=1'); handle = norm(fp[0] && fp[0].handle) }
  if (!handle) no_hace.push({ detalle: 'novedades propias', por_que: 'no hay cuenta propia de Instagram conocida' })
  else pedir('instagram_scraper', { usernames: [handle], resultsLimit: 3 }, 'cuenta @' + handle)
  // 3 · sedes: se re-leen con lo ya guardado (US$ 0) SIEMPRE después de raspar, y también si solo vencieron datos de sede
  if (sedes || acciones.length) acciones.push({ tipo: 'recolectar', funcion: 'recolectar_sedes', params: { client_id: c.id }, detalle: 're-leer las sedes con lo ya guardado', usd_prom: 0, usd_max: 0 })
  no_hace.push({ detalle: 'competidores y anuncios', por_que: 'fuera de la ronda firmada (A): no se adelanta' })
  salida.clientes.push({ cliente: c.id, nombre: c.name, corridas_reales_antes: hoyCorridas.length, vencidas_antes: vencidasAntes, acciones, no_hace })
}
return [{ json: salida }]

// ② EJECUTAR EL PLAN · CEREBRO · PONERSE AL DÍA (diario) · CC#2 · relevo 18
// Ejecuta SOLO lo que ① dejó en `acciones`: raspar por el Servicio de Apify (`respuesta`, sin ensayo) y re-leer sedes. Antes de CADA llamada vuelve a contar las corridas reales de hoy
// del cliente (el tope manda aunque el plan diga otra cosa). Mide: antes/después de lo vencido, filas, costo real de cada corrida (API de Apify) y duración.
// ETIQUETA las fotos PROPIAS nuevas sin etiqueta (bloque `etiquetarFotos`, topes escritos en ①; la etiqueta la escribe la ruta del portero), NO toca competidores ni anuncios, NO escribe a mano en ninguna tabla: lo guardado lo guarda el Servicio (como hoy) y `recolectar` (US$ 0).
const SB = 'https://ordaeyxvvvdqsznsecjx.supabase.co'
const API = 'https://zero-risk-platform.vercel.app'
const N8N = 'https://n8n-production-72be.up.railway.app'
const auth = { apikey: $env.SUPABASE_SERVICE_ROLE_KEY, Authorization: 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY }
const plan = $input.first().json
const TOPE_CORRIDAS = plan.topes.corridas_por_cliente
const hoy0 = new Date(); hoy0.setUTCHours(0, 0, 0, 0)
const http = async (o) => this.helpers.httpRequest({ json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 140000, ...o })
const salida = { ...plan, ejecutado_en: new Date().toISOString(), resultados: [] }
if (!plan.ejecutar) { salida.nota = 'EJECUTAR = falso: solo el plan, nada llamado'; return [{ json: salida }] }

// ───── BLOQUE · ETIQUETADO DIARIO (idéntico a scripts/n8n-nodos/cerebro-diario-etiquetar.js de la rama) ─────
// ETIQUETADO DIARIO · bloque del nodo «② Ejecutar el plan y medir» del flujo `EZXAFQvKZsJlvGNO` (Cerebro · ponerse al día, diario) · relevo 21 (CC#1, firma de Emilio «SI APROBADO»).
// El flujo pega este archivo TAL CUAL dentro del nodo ②; la prueba `__tests__/cerebro-diario-etiquetado.test.ts` ejecuta ESTE MISMO texto con una base y una ruta simuladas.
// Qué hace: después de raspar, pide `etiquetar` (la ruta del portero, UNA llamada al modelo por foto, sin reintentos) para cada foto PROPIA del cliente que todavía no tiene etiqueta.
//   · LEE solo el id y la marca de «etiquetada» de `client_social_images` (excepción declarada en el detector de flujos vivos) y el libro (`agent_invocations`) para contar intentos y gasto.
//   · NO escribe en ninguna tabla: la etiqueta la escribe la ruta del portero. Nunca manda `forzar` ni `solo_toma`.
// Topes (vienen escritos en el nodo ①, `plan.topes.etiquetar`): fotos por cliente y día · gasto de etiquetar por día (cualquier origen, leído del libro) · intentos por foto de por vida · paro si el modelo no responde.
async function etiquetarFotos(d) {
  const T = d.topes
  const salida = { tope: T, sin_etiqueta: 0, elegibles: 0, llamadas: [], gastado_usd: 0, gasto_de_hoy_antes_usd: null, agotadas: [], parado: null }
  const leer = async (url, headers) => d.leer(url, headers)
  const UUID = /^[0-9a-fA-F-]{36}$/
  if (!UUID.test(String(d.cliente))) { salida.parado = 'cliente_invalido'; return salida }
  // 1 · el gasto de HOY de quien etiqueta (también lo de una corrida a mano). Si no se puede leer, NO se etiqueta: un fallo de lectura nunca se lee como «hoy no se gastó nada».
  const hoy = await leer(d.SB + '/rest/v1/agent_invocations?select=cost_usd&agent_name=eq.etiquetador-del-cerebro&created_at=gte.' + d.hoy0 + '&limit=1000', d.auth)
  if (hoy.statusCode !== 200 || !Array.isArray(hoy.body)) { salida.parado = 'no_se_pudo_leer_el_gasto_de_hoy (HTTP ' + hoy.statusCode + ')'; return salida }
  const gastoHoy = hoy.body.reduce((s, x) => s + (Number(x.cost_usd) || 0), 0)
  salida.gasto_de_hoy_antes_usd = Number(gastoHoy.toFixed(6))
  // 2 · las fotos PROPIAS sin etiqueta, las más nuevas primero (se piden más que el tope para poder saltar las que ya agotaron sus intentos)
  const fotos = await leer(d.SB + '/rest/v1/client_social_images?select=id,etiquetada_en&client_id=eq.' + d.cliente + '&owner_role=eq.propio&etiquetada_en=is.null&estado=eq.ok&order=posted_at.desc.nullslast&limit=' + T.fotos_por_cliente_dia * 4, d.auth)
  if (fotos.statusCode !== 200 || !Array.isArray(fotos.body)) { salida.parado = 'no_se_pudo_leer_las_fotos (HTTP ' + fotos.statusCode + ')'; return salida }
  const ids = fotos.body.map((f) => String(f.id)).filter((id) => UUID.test(id))
  salida.sin_etiqueta = ids.length
  if (!ids.length) return salida
  // 3 · intentos de cada una = llamadas al modelo que se COBRARON (costo > 0) y no dejaron etiqueta. Una llamada cortada por falta de saldo cuesta 0 y no gasta un intento.
  const lib = await leer(d.SB + '/rest/v1/agent_invocations?select=metadata&agent_name=eq.etiquetador-del-cerebro&cost_usd=gt.0&metadata-%3E%3Efoto_id=in.(' + ids.join(',') + ')&limit=1000', d.auth)
  if (lib.statusCode !== 200 || !Array.isArray(lib.body)) { salida.parado = 'no_se_pudo_leer_los_intentos (HTTP ' + lib.statusCode + ')'; return salida }
  const intentos = {}
  for (const r of lib.body) { const k = r && r.metadata && r.metadata.foto_id; if (k) intentos[k] = (intentos[k] || 0) + 1 }
  const elegibles = []
  for (const id of ids) { if ((intentos[id] || 0) >= T.intentos_por_foto) salida.agotadas.push({ foto: id, intentos: intentos[id] }); else elegibles.push(id) }
  salida.elegibles = elegibles.length
  // 4 · una por una: antes de CADA llamada se comprueba el tope del día contra el peor caso de una foto
  let seguidasSinModelo = 0
  for (const id of elegibles) {
    if (salida.llamadas.length >= T.fotos_por_cliente_dia) { salida.parado = 'tope_de_fotos_del_cliente'; break }
    if (gastoHoy + salida.gastado_usd + T.peor_caso_usd > T.usd_dia) { salida.parado = 'tope_de_gasto_del_dia'; break }
    const t0 = Date.now()
    const r = await d.enviar(d.API + '/api/brain/portero/etiquetar', { cliente: d.cliente, foto: id, workflow_id: d.flujoId, workflow_execution_id: d.ejecucionId })
    const b = r.body && typeof r.body === 'object' ? r.body : {}
    const costo = typeof b.costo_usd === 'number' && b.costo_usd >= 0 ? b.costo_usd : 0
    salida.gastado_usd = Number((salida.gastado_usd + costo).toFixed(6))
    const ll = { foto: id, http: r.statusCode, modo: b.modo || null, llamo_al_modelo: b.llamo_al_modelo === true, escribio: b.escribio === true, costo_usd: costo, columnas_escritas: b.columnas_escritas || null, ms: Date.now() - t0 }
    if (r.statusCode !== 200) ll.error = String(b.error || b.detail || '').slice(0, 160)
    if (b.motivo_de_respaldo) ll.motivo_de_respaldo = b.motivo_de_respaldo
    salida.llamadas.push(ll)
    // la puerta cerrada (llave, flujo) o el modelo caído: no se sigue golpeando
    if (r.statusCode === 401 || r.statusCode === 403) { salida.parado = 'la_ruta_rechazo (HTTP ' + r.statusCode + ')'; break }
    seguidasSinModelo = b.llamo_al_modelo === true ? 0 : seguidasSinModelo + 1
    if (seguidasSinModelo >= 2) { salida.parado = 'el_modelo_no_responde (2 seguidas)'; break }
  }
  return salida
}
// ───── fin del bloque ─────

for (const c of plan.clientes) {
  const res = { cliente: c.cliente, nombre: c.nombre, llamadas: [], vencidas_antes_n: c.vencidas_antes.length }
  for (const a of c.acciones) {
    const t0 = Date.now()
    if (a.tipo === 'apify') {
      const hoy = await http({ url: SB + '/rest/v1/apify_raw?select=apify_function,created_at&client_id=eq.' + c.cliente + '&ensayo=eq.false&created_at=gte.' + hoy0.toISOString() + '&limit=200', method: 'GET', headers: auth })
      // una corrida = función + segundo (el Servicio deja varias filas por corrida)
      const n = Array.isArray(hoy.body) ? new Set(hoy.body.map((r) => r.apify_function + '|' + String(r.created_at).slice(0, 19))).size : 999
      if (n >= TOPE_CORRIDAS) { res.llamadas.push({ funcion: a.funcion, hecho: false, por_que: 'tope de corridas del día (' + n + '/' + TOPE_CORRIDAS + ')' }); continue }
      const r = await http({ url: N8N + '/webhook/apify-service-workflow', method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: { client_id: c.cliente, apify_function: a.funcion, params: a.params, destination: 'respuesta', dry_run: false, metadata: { llamado_por: 'cerebro-diario', calling_workflow_id: plan.flujo } } })
      const b = r.body && typeof r.body === 'object' ? r.body : {}
      const ll = { funcion: a.funcion, hecho: r.statusCode === 200 && b.ok === true, http: r.statusCode, ms: Date.now() - t0, apify_run_id: b.apify_run_id || null, sin_resultados: b.sin_resultados === true, guardado_en: b.guardado_en || null, cost_estimate_usd: b.cost_estimate_usd || 0, cero: b.cero ? (b.cero.clase || b.cero.motivo || 'cero') : null }
      if (!ll.hecho) ll.error = String(b.error || b.message || b.validation_errors || (r.body && r.body.toString ? r.body.toString().slice(0, 120) : '')).slice(0, 160)
      if (ll.apify_run_id && $env.APIFY_API_TOKEN) {
        const u = await http({ url: 'https://api.apify.com/v2/actor-runs/' + ll.apify_run_id + '?token=' + $env.APIFY_API_TOKEN, method: 'GET', headers: {} })
        const d = u.body && u.body.data
        if (d) { ll.costo_real_usd = d.usageTotalUsd === undefined ? null : Number(d.usageTotalUsd); ll.estado_apify = d.status }
      }
      res.llamadas.push(ll)
    } else if (a.tipo === 'recolectar') {
      const r = await http({ url: API + '/api/clients/sedes/recolectar', method: 'POST', headers: { 'x-api-key': $env.INTERNAL_API_KEY, 'Content-Type': 'application/json' }, body: a.params })
      const b = r.body && typeof r.body === 'object' ? r.body : {}
      res.llamadas.push({ funcion: a.funcion, hecho: r.statusCode === 200 && b.ok !== false, http: r.statusCode, ms: Date.now() - t0, error: b.ok === false ? String(b.error || '').slice(0, 120) : undefined })
    }
  }
  // después: ¿se re-fecharon las vencidas?
  const v = await http({ url: API + '/api/brain/portero/vencidos?cliente=' + c.cliente + '&dias=1', method: 'GET', headers: { 'x-api-key': $env.INTERNAL_API_KEY } })
  if (v.statusCode === 200 && v.body && v.body.vencidas) {
    const despues = v.body.vencidas.map((f) => f.ref)
    res.vencidas_despues_n = despues.length
    res.siguen_vencidas = c.vencidas_antes.filter((r) => despues.indexOf(r) !== -1).length
    res.ya_no_vencidas = c.vencidas_antes.filter((r) => despues.indexOf(r) === -1).length
    res.nuevas_vencidas = despues.filter((r) => c.vencidas_antes.indexOf(r) === -1).length
  } else res.vencidas_despues = 'no se pudo leer `vencidos` (HTTP ' + v.statusCode + ')'
  res.costo_real_total_usd = Number(res.llamadas.reduce((s, l) => s + (l.costo_real_usd || 0), 0).toFixed(4))
  // etiquetar las fotos propias nuevas (después de raspar). Un fallo aquí NO tumba el resto de la corrida.
  try { res.etiquetado = await etiquetarFotos({ SB, API, auth, hoy0: hoy0.toISOString(), cliente: c.cliente, topes: plan.topes.etiquetar, flujoId: plan.flujo, ejecucionId: String($execution.id), leer: (u, h) => http({ url: u, method: 'GET', headers: h }), enviar: (u, b) => http({ url: u, method: 'POST', headers: { 'x-api-key': $env.INTERNAL_API_KEY, 'Content-Type': 'application/json' }, body: b, timeout: 60000 }) }) } catch (e) { res.etiquetado = { error: String((e && e.message) || e).slice(0, 200) } }
  salida.resultados.push(res)
}
return [{ json: salida }]

// ① PLAN DEL DÍA · CEREBRO · PONERSE AL DÍA (diario) · CC#2 · relevo 18 (2026-10-08) · firmado por Emilio: sitio + sedes + Instagram propio. Competidores y anuncios: NO.
// Este nodo SOLO LEE y decide qué se hace, con los TOPES ESCRITOS AQUÍ. El nodo ② ejecuta lo que este nodo deja en `acciones` (y vuelve a comprobar el tope antes de cada llamada).
// «Cliente activo» = ALTA REALIZADA (Emilio 08-oct): no archivado ni dado de baja, con manual de marca y plan de 90 días. El alta no se toca.
const SB = 'https://ordaeyxvvvdqsznsecjx.supabase.co'
const API = 'https://zero-risk-platform.vercel.app'
const auth = { apikey: $env.SUPABASE_SERVICE_ROLE_KEY, Authorization: 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY }
const UUID = /^[0-9a-fA-F-]{36}$/
let viaWebhook = false
let entrada = {}
try { const w = $('Webhook · a mano (con llave)').first(); viaWebhook = true; entrada = (w.json && w.json.body) || {} } catch (e) { viaWebhook = false }
const SOLO = typeof entrada.cliente === 'string' && UUID.test(entrada.cliente) ? entrada.cliente : null
// por horario SIEMPRE se ejecuta; a mano solo si se pide `ejecutar: true` Y se nombra UN cliente (limita el alcance de una prueba)
const EJECUTAR = viaWebhook ? (entrada.ejecutar === true && SOLO !== null) : true
const DIAS = 1

// ── lo medido (243 corridas reales de Apify) · US$ por corrida
const COSTO = {
  website_content_scraper: { prom: 0.0228, max: 0.0536 },
  instagram_scraper: { prom: 0.0023, max: 0.0023 },
  recolectar_sedes: { prom: 0, max: 0 },
}
// ── TOPES ESCRITOS EN EL FLUJO (firmados): nada que vigilar
const TOPE_CORRIDAS_POR_CLIENTE_DIA = 6
const TOPE_USD_POR_CLIENTE_DIA = 0.3
const TOPE_USD_TOTAL_DIA = 3.0
// ── ETIQUETADO DIARIO (relevo 21 · firmado): fotos PROPIAS nuevas sin etiqueta, una llamada al modelo por foto (≈ US$ 0,009 medido en las 16 reales; peor caso 0,0286). Topes escritos aquí:
const TOPES_ETIQUETAR = { fotos_por_cliente_dia: 5, usd_dia: 0.1, intentos_por_foto: 2, peor_caso_usd: 0.0286 }
const POR_TABLA = { client_web_pages: 'pagina', client_social_images: 'instagram', client_sede_datos: 'sedes', client_sedes: 'sedes' }

const leer = async (url, headers) => this.helpers.httpRequest({ url, method: 'GET', json: true, headers, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 25000 })
const rest = async (ruta) => {
  const r = await leer(SB + '/rest/v1/' + ruta, auth)
  if (r.statusCode !== 200) throw new Error('LECTURA_FALLIDA · ' + ruta.slice(0, 60) + ' · HTTP ' + r.statusCode)
  return r.body
}
// una corrida de Apify puede dejar VARIAS filas en `apify_raw` (el Servicio guarda una por página leída, con el mismo instante): una corrida = función + segundo de creación
const corridasDe = (filas) => { const vistas = {}; for (const r of filas) vistas[r.apify_function + '|' + String(r.created_at).slice(0, 19)] = r.apify_function; return Object.keys(vistas).map((k) => vistas[k]) }
const norm = (h) => String(h || '').trim().toLowerCase().replace(/^@/, '')

const hoy0 = new Date(); hoy0.setUTCHours(0, 0, 0, 0)
const clientes = await rest('clients?select=id,name,status,archived_at,config&order=created_at.asc&limit=500')
// gasto máximo calculado de HOY en todos los clientes (corridas reales ya hechas × su máximo medido) para el tope total
const hoyTodos = await rest('apify_raw?select=apify_function,created_at&ensayo=eq.false&created_at=gte.' + hoy0.toISOString() + '&limit=1000')
let usdTotalHoyMax = 0
for (const f of corridasDe(hoyTodos)) usdTotalHoyMax += (COSTO[f] ? COSTO[f].max : 0.0536)

const salida = { flujo: 'EZXAFQvKZsJlvGNO', via: viaWebhook ? 'webhook a mano' : 'horario', ejecutar: EJECUTAR, solo_cliente: SOLO, generado_en: new Date().toISOString(), topes: { corridas_por_cliente: TOPE_CORRIDAS_POR_CLIENTE_DIA, usd_por_cliente: TOPE_USD_POR_CLIENTE_DIA, usd_total: TOPE_USD_TOTAL_DIA, etiquetar: TOPES_ETIQUETAR }, clientes: [], excluidos: [] }

for (const c of clientes) {
  if (SOLO && c.id !== SOLO) continue
  const esPrueba = /^prueba/i.test(String(c.id)) || /^prueba/i.test(String(c.name))
  const baja = ['churned', 'archived', 'inactive', 'lost', 'cancelled'].includes(String(c.status))
  const [manual, plan] = await Promise.all([
    rest('client_brand_books?select=id&client_id=eq.' + c.id + '&limit=1'),
    rest('client_historical_outputs?select=id,provenance_tag&client_id=eq.' + c.id + '&output_type=eq.campaign_plan_90d&limit=5'),
  ])
  const planReal = (plan || []).filter((p) => !(p.provenance_tag && typeof p.provenance_tag === 'object' && Object.keys(p.provenance_tag).some((k) => k.indexOf('prueba') === 0)))
  const motivos = []
  if (esPrueba) motivos.push('cliente de prueba')
  if (c.archived_at) motivos.push('archivado')
  if (baja) motivos.push('dado de baja (' + c.status + ')')
  if (!manual.length) motivos.push('sin manual de marca')
  if (!planReal.length) motivos.push('sin plan de 90 días')
  if (motivos.length) { salida.excluidos.push({ cliente: c.id, nombre: c.name, motivos }); continue }

  const hoyC = await rest('apify_raw?select=apify_function,created_at&client_id=eq.' + c.id + '&ensayo=eq.false&created_at=gte.' + hoy0.toISOString() + '&limit=200')
  const hoyCorridas = corridasDe(hoyC)
  let corridas = hoyCorridas.length, usdMax = 0
  for (const f of hoyCorridas) usdMax += (COSTO[f] ? COSTO[f].max : 0.0536)
  const acciones = [], no_hace = []
  const pedir = (funcion, params, detalle) => {
    const k = COSTO[funcion]
    if (corridas >= TOPE_CORRIDAS_POR_CLIENTE_DIA || usdMax + k.max > TOPE_USD_POR_CLIENTE_DIA || usdTotalHoyMax + k.max > TOPE_USD_TOTAL_DIA) { no_hace.push({ funcion, detalle, por_que: 'no cabe en el tope del día' }); return }
    corridas += 1; usdMax += k.max; usdTotalHoyMax += k.max
    acciones.push({ tipo: 'apify', funcion, params, detalle, usd_prom: k.prom, usd_max: k.max })
  }

  // 1 · lo vencido, agrupado por su FILA de origen (tabla → raspador: correspondencia estructural)
  const v = await leer(API + '/api/brain/portero/vencidos?cliente=' + c.id + '&dias=' + DIAS, { 'x-api-key': $env.INTERNAL_API_KEY })
  let sedes = false
  const vencidasAntes = []
  if (v.statusCode !== 200 || !v.body || v.body.estado === 'error_de_lectura') {
    no_hace.push({ detalle: 'no se pudo leer `vencidos` (HTTP ' + v.statusCode + ')', por_que: 'un fallo de lectura NUNCA se lee como «no vence nada»' })
  } else {
    for (const f of (v.body.vencidas || [])) vencidasAntes.push(f.ref)
    const grupos = new Map()
    for (const f of (v.body.vencidas || []).concat(v.body.por_vencer || [])) {
      const origen = String(f.ref || '').split('#')[0]
      const g = grupos.get(origen) || { origen, tabla: origen.split(':')[0], fichas: 0 }
      g.fichas += 1; grupos.set(origen, g)
    }
    for (const g of grupos.values()) {
      const que = POR_TABLA[g.tabla]
      const det = g.fichas + ' ficha(s) de ' + g.origen.slice(0, 48)
      if (que === 'pagina') {
        const fila = await rest('client_web_pages?select=url,owner_role&id=eq.' + g.origen.split(':')[1] + '&limit=1')
        const propia = fila[0] && fila[0].owner_role === 'propio'
        if (!fila[0] || !fila[0].url) no_hace.push({ detalle: det, por_que: 'la página de origen no tiene dirección' })
        else if (!propia) no_hace.push({ detalle: det, por_que: 'página de un competidor: competidores NO están firmados en esta ronda' })
        else pedir('website_content_scraper', { url: fila[0].url }, det + ' · ' + fila[0].url)
      } else if (que === 'sedes') {
        sedes = true
      } else if (que === 'instagram') {
        // las fotos propias no vencen; si alguna lo hiciera, la corrida de Instagram de abajo ya las cubre
      } else {
        no_hace.push({ detalle: det, por_que: 'su tabla (' + g.tabla + ') no se renueva raspando en esta ronda' })
      }
    }
  }
  // 2 · novedades propias: Instagram propio (la cuenta sale de la ficha del cliente; si falta, de sus fotos propias)
  const cfgIg = norm(c.config && c.config.apify && c.config.apify.own_handles && c.config.apify.own_handles.instagram)
  let handle = cfgIg
  if (!handle) { const fp = await rest('client_social_images?select=handle&client_id=eq.' + c.id + '&owner_role=eq.propio&limit=1'); handle = norm(fp[0] && fp[0].handle) }
  if (!handle) no_hace.push({ detalle: 'novedades propias', por_que: 'no hay cuenta propia de Instagram conocida' })
  else pedir('instagram_scraper', { usernames: [handle], resultsLimit: 3 }, 'cuenta @' + handle)
  // 3 · sedes: se re-leen con lo ya guardado (US$ 0) SIEMPRE después de raspar, y también si solo vencieron datos de sede
  if (sedes || acciones.length) acciones.push({ tipo: 'recolectar', funcion: 'recolectar_sedes', params: { client_id: c.id }, detalle: 're-leer las sedes con lo ya guardado', usd_prom: 0, usd_max: 0 })
  no_hace.push({ detalle: 'competidores y anuncios', por_que: 'fuera de la ronda firmada (A): no se adelanta' })
  salida.clientes.push({ cliente: c.id, nombre: c.name, corridas_reales_antes: hoyCorridas.length, vencidas_antes: vencidasAntes, acciones, no_hace })
}
return [{ json: salida }]

// ② EJECUTAR EL PLAN · CEREBRO · PONERSE AL DÍA (diario) · CC#2 · relevo 18
// Ejecuta SOLO lo que ① dejó en `acciones`: raspar por el Servicio de Apify (`respuesta`, sin ensayo) y re-leer sedes. Antes de CADA llamada vuelve a contar las corridas reales de hoy
// del cliente (el tope manda aunque el plan diga otra cosa). Mide: antes/después de lo vencido, filas, costo real de cada corrida (API de Apify) y duración.
// ETIQUETA las fotos PROPIAS nuevas sin etiqueta (bloque `etiquetarFotos`, topes escritos en ①; la etiqueta la escribe la ruta del portero), NO toca competidores ni anuncios, NO escribe a mano en ninguna tabla: lo guardado lo guarda el Servicio (como hoy) y `recolectar` (US$ 0).
const SB = 'https://ordaeyxvvvdqsznsecjx.supabase.co'
const API = 'https://zero-risk-platform.vercel.app'
const N8N = 'https://n8n-production-72be.up.railway.app'
const auth = { apikey: $env.SUPABASE_SERVICE_ROLE_KEY, Authorization: 'Bearer ' + $env.SUPABASE_SERVICE_ROLE_KEY }
const plan = $input.first().json
const TOPE_CORRIDAS = plan.topes.corridas_por_cliente
const hoy0 = new Date(); hoy0.setUTCHours(0, 0, 0, 0)
const http = async (o) => this.helpers.httpRequest({ json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 140000, ...o })
const salida = { ...plan, ejecutado_en: new Date().toISOString(), resultados: [] }
if (!plan.ejecutar) { salida.nota = 'EJECUTAR = falso: solo el plan, nada llamado'; return [{ json: salida }] }

// ───── BLOQUE · ETIQUETADO DIARIO (idéntico a scripts/n8n-nodos/cerebro-diario-etiquetar.js de la rama) ─────
// ETIQUETADO DIARIO · bloque del nodo «② Ejecutar el plan y medir» del flujo `EZXAFQvKZsJlvGNO` (Cerebro · ponerse al día, diario) · relevo 21 (CC#1, firma de Emilio «SI APROBADO»).
// El flujo pega este archivo TAL CUAL dentro del nodo ②; la prueba `__tests__/cerebro-diario-etiquetado.test.ts` ejecuta ESTE MISMO texto con una base y una ruta simuladas.
// Qué hace: después de raspar, pide `etiquetar` (la ruta del portero, UNA llamada al modelo por foto, sin reintentos) para cada foto PROPIA del cliente que todavía no tiene etiqueta.
//   · LEE solo el id y la marca de «etiquetada» de `client_social_images` (excepción declarada en el detector de flujos vivos) y el libro (`agent_invocations`) para contar intentos y gasto.
//   · NO escribe en ninguna tabla: la etiqueta la escribe la ruta del portero. Nunca manda `forzar` ni `solo_toma`.
// Topes (vienen escritos en el nodo ①, `plan.topes.etiquetar`): fotos por cliente y día · gasto de etiquetar por día (cualquier origen, leído del libro) · intentos por foto de por vida · paro si el modelo no responde.
async function etiquetarFotos(d) {
  const T = d.topes
  const salida = { tope: T, sin_etiqueta: 0, elegibles: 0, llamadas: [], gastado_usd: 0, gasto_de_hoy_antes_usd: null, agotadas: [], parado: null }
  const leer = async (url, headers) => d.leer(url, headers)
  const UUID = /^[0-9a-fA-F-]{36}$/
  if (!UUID.test(String(d.cliente))) { salida.parado = 'cliente_invalido'; return salida }
  // 1 · el gasto de HOY de quien etiqueta (también lo de una corrida a mano). Si no se puede leer, NO se etiqueta: un fallo de lectura nunca se lee como «hoy no se gastó nada».
  const hoy = await leer(d.SB + '/rest/v1/agent_invocations?select=cost_usd&agent_name=eq.etiquetador-del-cerebro&created_at=gte.' + d.hoy0 + '&limit=1000', d.auth)
  if (hoy.statusCode !== 200 || !Array.isArray(hoy.body)) { salida.parado = 'no_se_pudo_leer_el_gasto_de_hoy (HTTP ' + hoy.statusCode + ')'; return salida }
  const gastoHoy = hoy.body.reduce((s, x) => s + (Number(x.cost_usd) || 0), 0)
  salida.gasto_de_hoy_antes_usd = Number(gastoHoy.toFixed(6))
  // 2 · las fotos PROPIAS sin etiqueta, las más nuevas primero (se piden más que el tope para poder saltar las que ya agotaron sus intentos)
  const fotos = await leer(d.SB + '/rest/v1/client_social_images?select=id,etiquetada_en&client_id=eq.' + d.cliente + '&owner_role=eq.propio&etiquetada_en=is.null&estado=eq.ok&order=posted_at.desc.nullslast&limit=' + T.fotos_por_cliente_dia * 4, d.auth)
  if (fotos.statusCode !== 200 || !Array.isArray(fotos.body)) { salida.parado = 'no_se_pudo_leer_las_fotos (HTTP ' + fotos.statusCode + ')'; return salida }
  const ids = fotos.body.map((f) => String(f.id)).filter((id) => UUID.test(id))
  salida.sin_etiqueta = ids.length
  if (!ids.length) return salida
  // 3 · intentos de cada una = llamadas al modelo que se COBRARON (costo > 0) y no dejaron etiqueta. Una llamada cortada por falta de saldo cuesta 0 y no gasta un intento.
  const lib = await leer(d.SB + '/rest/v1/agent_invocations?select=metadata&agent_name=eq.etiquetador-del-cerebro&cost_usd=gt.0&metadata-%3E%3Efoto_id=in.(' + ids.join(',') + ')&limit=1000', d.auth)
  if (lib.statusCode !== 200 || !Array.isArray(lib.body)) { salida.parado = 'no_se_pudo_leer_los_intentos (HTTP ' + lib.statusCode + ')'; return salida }
  const intentos = {}
  for (const r of lib.body) { const k = r && r.metadata && r.metadata.foto_id; if (k) intentos[k] = (intentos[k] || 0) + 1 }
  const elegibles = []
  for (const id of ids) { if ((intentos[id] || 0) >= T.intentos_por_foto) salida.agotadas.push({ foto: id, intentos: intentos[id] }); else elegibles.push(id) }
  salida.elegibles = elegibles.length
  // 4 · una por una: antes de CADA llamada se comprueba el tope del día contra el peor caso de una foto
  let seguidasSinModelo = 0
  for (const id of elegibles) {
    if (salida.llamadas.length >= T.fotos_por_cliente_dia) { salida.parado = 'tope_de_fotos_del_cliente'; break }
    if (gastoHoy + salida.gastado_usd + T.peor_caso_usd > T.usd_dia) { salida.parado = 'tope_de_gasto_del_dia'; break }
    const t0 = Date.now()
    const r = await d.enviar(d.API + '/api/brain/portero/etiquetar', { cliente: d.cliente, foto: id, workflow_id: d.flujoId, workflow_execution_id: d.ejecucionId })
    const b = r.body && typeof r.body === 'object' ? r.body : {}
    const costo = typeof b.costo_usd === 'number' && b.costo_usd >= 0 ? b.costo_usd : 0
    salida.gastado_usd = Number((salida.gastado_usd + costo).toFixed(6))
    const ll = { foto: id, http: r.statusCode, modo: b.modo || null, llamo_al_modelo: b.llamo_al_modelo === true, escribio: b.escribio === true, costo_usd: costo, columnas_escritas: b.columnas_escritas || null, ms: Date.now() - t0 }
    if (r.statusCode !== 200) ll.error = String(b.error || b.detail || '').slice(0, 160)
    if (b.motivo_de_respaldo) ll.motivo_de_respaldo = b.motivo_de_respaldo
    salida.llamadas.push(ll)
    // la puerta cerrada (llave, flujo) o el modelo caído: no se sigue golpeando
    if (r.statusCode === 401 || r.statusCode === 403) { salida.parado = 'la_ruta_rechazo (HTTP ' + r.statusCode + ')'; break }
    seguidasSinModelo = b.llamo_al_modelo === true ? 0 : seguidasSinModelo + 1
    if (seguidasSinModelo >= 2) { salida.parado = 'el_modelo_no_responde (2 seguidas)'; break }
  }
  return salida
}
// ───── fin del bloque ─────

for (const c of plan.clientes) {
  const res = { cliente: c.cliente, nombre: c.nombre, llamadas: [], vencidas_antes_n: c.vencidas_antes.length }
  for (const a of c.acciones) {
    const t0 = Date.now()
    if (a.tipo === 'apify') {
      const hoy = await http({ url: SB + '/rest/v1/apify_raw?select=apify_function,created_at&client_id=eq.' + c.cliente + '&ensayo=eq.false&created_at=gte.' + hoy0.toISOString() + '&limit=200', method: 'GET', headers: auth })
      // una corrida = función + segundo (el Servicio deja varias filas por corrida)
      const n = Array.isArray(hoy.body) ? new Set(hoy.body.map((r) => r.apify_function + '|' + String(r.created_at).slice(0, 19))).size : 999
      if (n >= TOPE_CORRIDAS) { res.llamadas.push({ funcion: a.funcion, hecho: false, por_que: 'tope de corridas del día (' + n + '/' + TOPE_CORRIDAS + ')' }); continue }
      const r = await http({ url: N8N + '/webhook/apify-service-workflow', method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: { client_id: c.cliente, apify_function: a.funcion, params: a.params, destination: 'respuesta', dry_run: false, metadata: { llamado_por: 'cerebro-diario', calling_workflow_id: plan.flujo } } })
      const b = r.body && typeof r.body === 'object' ? r.body : {}
      const ll = { funcion: a.funcion, hecho: r.statusCode === 200 && b.ok === true, http: r.statusCode, ms: Date.now() - t0, apify_run_id: b.apify_run_id || null, sin_resultados: b.sin_resultados === true, guardado_en: b.guardado_en || null, cost_estimate_usd: b.cost_estimate_usd || 0, cero: b.cero ? (b.cero.clase || b.cero.motivo || 'cero') : null }
      if (!ll.hecho) ll.error = String(b.error || b.message || b.validation_errors || (r.body && r.body.toString ? r.body.toString().slice(0, 120) : '')).slice(0, 160)
      if (ll.apify_run_id && $env.APIFY_API_TOKEN) {
        const u = await http({ url: 'https://api.apify.com/v2/actor-runs/' + ll.apify_run_id + '?token=' + $env.APIFY_API_TOKEN, method: 'GET', headers: {} })
        const d = u.body && u.body.data
        if (d) { ll.costo_real_usd = d.usageTotalUsd === undefined ? null : Number(d.usageTotalUsd); ll.estado_apify = d.status }
      }
      res.llamadas.push(ll)
    } else if (a.tipo === 'recolectar') {
      const r = await http({ url: API + '/api/clients/sedes/recolectar', method: 'POST', headers: { 'x-api-key': $env.INTERNAL_API_KEY, 'Content-Type': 'application/json' }, body: a.params })
      const b = r.body && typeof r.body === 'object' ? r.body : {}
      res.llamadas.push({ funcion: a.funcion, hecho: r.statusCode === 200 && b.ok !== false, http: r.statusCode, ms: Date.now() - t0, error: b.ok === false ? String(b.error || '').slice(0, 120) : undefined })
    }
  }
  // después: ¿se re-fecharon las vencidas?
  const v = await http({ url: API + '/api/brain/portero/vencidos?cliente=' + c.cliente + '&dias=1', method: 'GET', headers: { 'x-api-key': $env.INTERNAL_API_KEY } })
  if (v.statusCode === 200 && v.body && v.body.vencidas) {
    const despues = v.body.vencidas.map((f) => f.ref)
    res.vencidas_despues_n = despues.length
    res.siguen_vencidas = c.vencidas_antes.filter((r) => despues.indexOf(r) !== -1).length
    res.ya_no_vencidas = c.vencidas_antes.filter((r) => despues.indexOf(r) === -1).length
    res.nuevas_vencidas = despues.filter((r) => c.vencidas_antes.indexOf(r) === -1).length
  } else res.vencidas_despues = 'no se pudo leer `vencidos` (HTTP ' + v.statusCode + ')'
  res.costo_real_total_usd = Number(res.llamadas.reduce((s, l) => s + (l.costo_real_usd || 0), 0).toFixed(4))
  // etiquetar las fotos propias nuevas (después de raspar). Un fallo aquí NO tumba el resto de la corrida.
  try { res.etiquetado = await etiquetarFotos({ SB, API, auth, hoy0: hoy0.toISOString(), cliente: c.cliente, topes: plan.topes.etiquetar, flujoId: plan.flujo, ejecucionId: String($execution.id), leer: (u, h) => http({ url: u, method: 'GET', headers: h }), enviar: (u, b) => http({ url: u, method: 'POST', headers: { 'x-api-key': $env.INTERNAL_API_KEY, 'Content-Type': 'application/json' }, body: b, timeout: 60000 }) }) } catch (e) { res.etiquetado = { error: String((e && e.message) || e).slice(0, 200) } }
  salida.resultados.push(res)
}
return [{ json: salida }]
